// model/player.mjs -- the shutdown ladder, the play fork, the adopted-player check and the event router. One part of Model.mjs (D-REL-5); its import and export lines are generated by split-model.mjs on the dev branch.
import {
  STOP_QUIT_GRACE_MS, STOP_KILL_GRACE_MS, HEALTH_SKIPS_BEFORE_RESTART,
  PLAYER_STASH_SCHEMA, PLAYER_ORPHAN_GRACE_SEC, PLAYER_GENERIC_FAILURE,
  PLAYER_LOG_TAIL, PLAYER_ENTRY_OWNERS
} from "./build.mjs"
import {
  str, asList, keyedMap, ownKeyValue, trimEndSpace
} from "./text.mjs"
import {
  parseJsonObject
} from "./settings.mjs"
import {
  parseRewind
} from "./rewind.mjs"
import {
  redactUrls
} from "./privacy.mjs"
import {
  sourceKey
} from "./sources.mjs"

// ------------------------------------------------------------ player shutdown

// Next rung of the shutdown ladder (D-LIVE-17). `stage` is the rung already
// taken: "" -> `quit` over IPC, "quit" -> SIGTERM, "term" -> SIGKILL, after
// which only the exit is awaited (nothing to send, no wait to arm).
function stopEscalation(stage) {
  var s = str(stage)
  if (s === "") return { action: "quit", signal: 0, waitMs: STOP_QUIT_GRACE_MS }
  if (s === "quit") return { action: "term", signal: 15, waitMs: STOP_KILL_GRACE_MS }
  if (s === "term") return { action: "kill", signal: 9, waitMs: 0 }
  return { action: "kill", signal: 0, waitMs: 0 }
}

// One health-timer tick (D-LIVE-17). `skips` counts the ticks skipped in a
// row because a helper call was in flight, `busy` says whether one is in
// flight now: check = run the status probe, restart = treat the player as
// unresponsive without probing (HEALTH_SKIPS_BEFORE_RESTART busy ticks).
function healthTick(skips, busy) {
  var n = busy ? Math.max(0, Math.floor(Number(skips) || 0)) + 1 : 0
  var restart = !!busy && n >= HEALTH_SKIPS_BEFORE_RESTART
  return { check: !busy, restart: restart, skips: restart ? 0 : n }
}

// ---- D-PLY-35 (2026-10-28): the player slot's watchdog, derived ----
//
// The shell's playerWatchdog TERMs a `player start|restart|probe` that runs
// longer than this. It was one 12 s constant for all three, and a start's own
// bounds add up past it: lock 6 s + spawn 5 s + first load 3 s is already
// 14 s. Measured on dev 2026-10-28 (QA-RESULTS "D-PLY-35", dev branch),
// headless and in a nested cage: a start that waited out a held lock, a slow
// spawn and its first-load window was TERMed at 12 s, a second AFTER its
// loadfile; the player it had started went on to play the channel with the
// shell's observer off, `nowPlaying` null, the session record retired, and a
// "Could not start playback" card on screen. The next play adopted it.
//
// So the bound is derived per verb from the helper's own bounds, mirrored in
// PLAYER_BOUNDS and pinned on both sides by the shared player-bounds fixture
// (dev branch: the python half reads each one off the helper by name, and the
// shell passes none of the timeout flags, so the helper's defaults are the
// bounds). A verb's bound is its longest path through the helper's code with
// every wait it SURVIVES at its full bound, the one wait that ends it, and a
// margin:
//   ladder(""): the quit rung, which counts its own IPC (a connect and a
//     request) inside its grace and runs past it when they are longer, then
//     SIGTERM's grace, the kill rung's settle and the final one (stop_ladder)
//   ladder("term"): SIGTERM's grace and the two settles
//   wedged: a found player that does not answer the start's probe (connect
//     and request at their bound), then the whole ladder (adopt_or_spawn).
//     A RESTART meets it too, after its own ladder from term: a player in
//     uninterruptible sleep acts on neither signal, so that ladder can end
//     with it still there, and adopt_or_spawn, which runs next, finds it,
//     probes it and ladders it again from quit. So a restart's bound is a
//     start's plus its own ladder and settle (the recheck walked the
//     shipping code under a virtual clock: 41.12 s on that path, past the
//     35.45 s this first said; the player-bounds walk, dev branch)
//   spawn: the settle's one connect, the pid and exec pipes, the bind window,
//     and the last probe of it, which can start just inside the window
//   tail: the larger of the `no_socket` refusal (the spawn laddered from
//     term, then a settle) and the load (the one request after the loadfile
//     whose timeout does not end the verb, then the first-load window)
// What is NOT summed is every other request at its bound: a request that
// reaches its bound raises and ends the verb (MpvIpc.request), so only an mpv
// answering each of a start's twenty-odd requests just inside 2 s could run a
// verb past this. That residual is recovered, not bounded: a start the
// watchdog stopped is no verdict, and the reattach probe decides what it left
// (Service.qml, handlePlayerResult). The margin is what no bound cuts: the
// interpreter and the stub's compile (a whole `player probe` with no player,
// 259-306 ms at load 3.2), a 10,000-channel cache read (a start that resolves
// its id in one, 356-390 ms), the /proc scans and the poll overshoots; 5 s is
// twelve times that. "" is no verb: after a reply the same Timer bounds the
// birth edge (`playerPending` that no socket confirmed), unchanged at 12 s.
var PLAYER_BOUNDS = {
  lockMs: 6000,           // DEFAULT_LOCK_TIMEOUT
  lockPollMs: 50,         // LOCK_POLL_S
  spawnMs: 5000,          // DEFAULT_SPAWN_TIMEOUT: the exec pipe, then the bind window
  spawnPidMs: 2000,       // SPAWN_PID_TIMEOUT: the grandchild's pid pipe
  firstLoadMs: 3000,      // DEFAULT_FIRST_LOAD_TIMEOUT
  ipcMs: 2000,            // DEFAULT_IPC_TIMEOUT: one connect, or one request
  settleMs: 500,          // STOP_SETTLE_MS (not Service.qml's stopSettleMs)
  settleConnectMs: 200,   // SETTLE_CONNECT_TIMEOUT: socket_is_dead's one connect
  settleLockMs: 500       // SETTLE_LOCK_TIMEOUT: the probe's settle under the lock
}
var PLAYER_WATCHDOG_MARGIN_MS = 5000
var PLAYER_BIRTH_EDGE_MS = 12000

// The stop ladder's longest run from its first rung: "" (quit) or "term".
function playerLadderMs(fromRung) {
  var tail = STOP_KILL_GRACE_MS + 2 * PLAYER_BOUNDS.settleMs
  if (str(fromRung) === "term") return tail
  return Math.max(STOP_QUIT_GRACE_MS, 2 * PLAYER_BOUNDS.ipcMs) + tail
}

// The shell's watchdog over one run of `kind` on the player slot, in ms:
// "start", "restart", "probe", or "" for the birth edge. Anything else, a
// string or not, gets the longest verb's, never a shorter one.
function playerWatchdogMs(kind) {
  var b = PLAYER_BOUNDS
  var k = typeof kind === "string" ? kind : "?"
  var lock = b.lockMs + b.lockPollMs
  var spawn = b.settleConnectMs + b.spawnPidMs + 2 * b.spawnMs + 2 * b.ipcMs
  var tail = Math.max(playerLadderMs("term") + b.settleConnectMs, b.ipcMs + b.firstLoadMs)
  // Restart on adoption (2026-11-01): `carry` -- a found player another build
  // launched answers its probe and is REPLACED: its volume, mute, fullscreen
  // and pause read inside one ipcMs (bounded_requests), the three set on the
  // new player inside another. The wedged path's 2 * ipcMs is the same probe,
  // so the replace path is the wedged one plus these two (walked: 42.07 s, past
  // the 38.25 s the bound left without them; lane RA's M9).
  var carry = 2 * b.ipcMs
  if (k === "start") return lock + 2 * b.ipcMs + carry + playerLadderMs("") + spawn + tail + PLAYER_WATCHDOG_MARGIN_MS
  if (k === "restart") return lock + playerLadderMs("term") + b.settleConnectMs + 2 * b.ipcMs + playerLadderMs("") + spawn + tail + PLAYER_WATCHDOG_MARGIN_MS
  if (k === "probe") return Math.max(3 * b.ipcMs, b.settleLockMs + b.lockPollMs + b.settleConnectMs) + PLAYER_WATCHDOG_MARGIN_MS
  if (k === "") return PLAYER_BIRTH_EDGE_MS
  return Math.max(playerWatchdogMs("start"), playerWatchdogMs("restart"), playerWatchdogMs("probe"))
}

// ---- D-PLY-11: the play fork ----
//
// What the shell decides when a channel is asked for, lifted here so it can
// be stated in vectors instead of living where no test can reach it
// (engineering rule 12 (dev branch)). Checked against Service.qml's play() by the lane that
// wired it; if the two ever disagree, the shipping fork is right.
//
//   start  spawn or adopt a player and play there (`player start`)
//   zap    a running player, switch it over the socket (`play`)
//   queue  a zap is already in flight; remember the intent instead
//
// The row that matters for D-PLY-11 is `playerPending && !socketAttached`:
// the player is starting and has not bound its socket, `playerUp` is already
// true because pending counts, and the fork therefore answers "zap" - a zap
// aimed at a socket nothing is listening on yet. That state is no longer a
// hypothesis: wave two measured it on a real shell (ruling CL9,
// QA-RESULTS.md (dev branch) D1) at TEN user-visible divergences in twenty cold
// concurrent bursts, none in ten warm and none in six cold serial, with the
// mechanism observed rather than inferred - a change wins the socket and the
// cold start's own `apply_channel` lands after it.
//
// The fork itself is NOT the defect and is deliberately left as it is. A zap
// aimed at a socket that is about to exist is how a burst stays responsive,
// and CL4 forbids the instrument that would order the two slots. What was
// wrong is what happened at the far end: the start applied its channel
// unconditionally. That is fixed in the helper (`player start` stands down
// when it finds a newer channel on a player it just spawned) and repaired
// here by `sessionIntentRepair` and `reconcileVerdict` below.
//
// Restart on adoption (2026-11-01): `restartOwed` -- the adopted player was
// launched by another build and its replacement is owed -- answers "start":
// a user's channel change is then a `player start` of the new channel, which
// replaces the older player in the same helper call, so the replacement and
// the zap are one event. (A zap there would be refused by the helper's build
// gate and routed to the same start, a round trip later.) Service.qml's
// play() calls this function since the same change (F-GATE-18, rule 12).
function playFork(state) {
  var s = state || {}
  var playerUp = !!s.socketAttached || !!s.playerPending
  if (!playerUp || s.stopping || s.restartOwed === true) return "start"
  if (s.controlBusy) return "queue"
  return "zap"
}

// True when the fork above sends a zap at a player that has not bound its
// socket yet. Reporting only - it changes nothing.
function playForkBlind(state) {
  var s = state || {}
  return playFork(s) === "zap" && !s.socketAttached
}

// `play --id ... --socket ... --cache-dir ...`, plus the additive session
// flags. Lifted out of Service.qml.playArgs (engineering rule 12 (dev branch)): the decision
// that SKIPS `--scope`/`--since` is the decision that skips the stash write
// at the far end (`cmd_play` computes `session = bool(scope or since)`), and
// it was the one argv builder in the file with no vectors anywhere.
//
// The flags go on only when the record being zapped is the one the shell
// currently wants. A drained burst can issue an id that is no longer
// `nowPlaying`, and stamping that record's scope and start time onto a
// different channel would be worse than leaving the stash alone.
function zapArgs(socket, cacheDir, key, nowPlaying) {
  var id = str(key)
  var argv = ["play", "--id", id, "--socket", str(socket), "--cache-dir", str(cacheDir)]
  var np = nowPlaying || null
  if (!np || str(np.id) !== id) return argv
  var scope = str(np.launchedFrom)
  if (scope !== "") argv = argv.concat(["--scope", scope])
  var since = Math.floor(Number(np.since))
  if (isFinite(since) && since > 0) argv = argv.concat(["--since", String(since)])
  return argv
}

// A reply the shell could not READ, as distinct from one that says the
// switch failed. The status branch has had this guard since the beginning -
// "neither healthy nor a strike, so a missing subcommand never reaps a
// working player" - and the play branch never grew it, so an empty stdout or
// a python traceback (both parse to `no_output`) took the rollback.
//
// `helper_damaged` (D-REL-7) is the stub refusing to start over a missing or
// damaged part. It used to reach the shell as an empty stdout, `no_output`,
// and it routes exactly as that did -- on this branch and on the status
// branch (helperCannotTell) -- because nothing ran: no switch failed, no
// player misbehaved. Only the sentence changed (settings.mjs maps the code).
var PLAY_UNREADABLE = ["no_output", "not_implemented", "unknown_channel", "no_cache", "helper_damaged"]

// The status branch's "cannot tell": a helper that could not answer is
// neither healthy nor a health strike, so a stub or a damaged install never
// reaps a working player by restarting it through the same broken helper.
var HELPER_CANNOT_TELL = ["not_implemented", "no_output", "helper_damaged"]

function helperCannotTell(code) {
  return HELPER_CANNOT_TELL.indexOf(str(code)) !== -1
}
// A refusal, not a verdict. `busy` cannot reach a zap today - `cmd_play`
// takes no lock - and routing it is the first half of ruling CL4's order:
// refusals first, THEN a sequence number and the lock. Without this it falls
// to the rollback, which is why CL4 says giving `play` the lock now would
// manufacture the failure it is meant to remove.
var PLAY_RETRYABLE = ["ipc_error", "busy"]

// What a failed `play` reply means for the shell.
//
//   start    the player is gone; `player start` adopts or spawns, so the
//            same call is right either way
//   retry    the player did not answer, or something else held the lock:
//            back off and re-issue rather than losing the zap
//   unknown  cannot tell. Record it, tell nobody, change nothing
//   failed   the switch really did not happen; the player still plays the
//            channel before it, so the label goes back with it
function playFailureVerdict(code, context) {
  var ctx = context || {}
  var word = str(code)
  if (word === "not_running" && ctx.nowPlaying === true) return "start"
  if (PLAY_RETRYABLE.indexOf(word) !== -1) {
    if (ctx.playerUp === true && ctx.nowPlaying === true && ctx.userStopped !== true
        && ctx.retriesLeft === true) return "retry"
    // Out of retries: a timeout really is a failed switch, a refusal never
    // was one.
    return word === "ipc_error" ? "failed" : "unknown"
  }
  if (PLAY_UNREADABLE.indexOf(word) !== -1) return "unknown"
  return "failed"
}

// D-PLY-32 (2026-10-28): what a FAILED `player start|restart` reply says
// about the channel it was asked to play, once the service has taken the
// codes it handles before this (`superseded`, `mpv_missing`, and `busy` and
// `no_socket` while retries are left). Until now every one of them marked
// the channel failed and toasted "Stream failed", so with the runtime folder
// broken every channel the user tried turned red and dropped out of the zap
// ring for 14 days, for a fault of this machine.
//
//   channel  the refusal is about the channel's own playlist entry: mark it
//            and tell the user the stream failed
//   local    anything else: the stream was never contacted, so the reply is
//            no verdict on it. Record the reason, mark nothing
//
// A failed start REPLY is never a verdict on the stream. A stream that fails
// to load reaches the shell as an OK reply whose `firstLoad.state` is
// "failed" (playerFirstLoadFailed), or as the socket's EOF judged by
// endedReport (handlePlayerGone); neither comes through here. What the
// helper's `player start` can refuse with, read in bin/helper on 2026-10-28,
// and where:
//   player_target   no_cache (channels.json missing or unreadable),
//                   unknown_channel (the cache does not hold the id),
//                   unsupported_scheme (the entry's own URL: a scheme or a
//                   form is_stream_url refuses, or, since D-SINK-87, an
//                   address naming a host the player would read in a form
//                   no host name or port may take)
//   player_runtime  folder_unusable, runtime_unwritable
//   check_socket_path  socket_path_blocked
//   acquire_lock    runtime_unwritable, busy
//   check_seq       superseded
//   adopt_or_spawn  mpv_missing, spawn_failed, no_socket
//   apply_channel   tls_unverified (read off the PLAYER before the channel
//                   is touched), ipc_error (the connection closed or timed
//                   out; mpv 0.41.0 was measured accepting every
//                   channel-shaped value -- NUL, C0, C1, 70,000 characters,
//                   200 header fields -- on the three header properties and
//                   loadfile, so no channel's data makes it refuse)
//   main()          internal, too_large, folder_unusable
//   the stub        helper_damaged
//   the shell       no_output (nothing on stdout: a crash, argparse, the
//                   player slot's watchdog TERM), `error` (a reply with no
//                   code: parseHelperStatus)
// Only `unsupported_scheme` is about the entry, and only a cache this
// helper's parser would not write can carry one (it skips such lines), so
// it is the one code listed. This list is the START path's, and not every
// start reply that carries it is told: Service.qml's start tail tells it (a
// card and a mark, unless the user has stopped since) for a start or restart
// sent with no player playing on, and for the automatic restart of another
// build's player, which it stops; a start refused while the player it
// observes plays on -- a channel change while another build's player is
// still owed its restart sends one (playFork) -- is D-PLY-52's
// refusedWhilePlaying, which puts the label back and tells nothing. On a zap
// into a running player the same code comes back from `play`, which
// playFailureVerdict reads as `failed` -- no card and no mark, D-PLY-42's
// untold refusal (open, the owner's call) -- so a next or previous zap
// lands on that channel again until the cache is refetched.
//
// A list of the CHANNEL code rather than a fourth list of local ones, and
// on purpose: marking is the costly direction, so a code the helper grows
// later (D-PLY-31 names one) reads local until someone shows it is about
// the entry. That also makes this the superset of the three lists that
// already say "local" -- HELPER_CANNOT_TELL, PLAY_UNREADABLE and the probe's
// PROBE_LOCAL_REFUSALS (model/sources.mjs) -- by construction, and the node
// suite holds it: no code on any of them reads "channel" here. They stay
// three lists because they answer other questions about other verbs, and a
// code's meaning moves with the verb: `too_large` on the probe is the
// provider's source over its bound ("from <host>" is right), on a player
// verb it is this helper's own memory; `busy` there is a fetch, here the
// player lock; `unknown_channel` and `no_cache` are no probe's codes at all.
//
// D-SINK-58 (2026-10-29): `local_address` joins it. player_target now runs
// the parse's host rule again against the cache's own record of its
// playlist, so a cache nothing checked -- one from before the destination
// rules, whose refresh failed -- refuses a channel on a LAN or loopback
// literal that its playlist chose. That refusal is about the entry.
// D-SINK-89 (2026-11-09): and so is the same code for a cached channel whose
// address names a host of one label from a playlist that is not local.
var PLAYER_START_CHANNEL_REFUSALS = ["unsupported_scheme", "local_address"]

function playerStartFailure(code) {
  return PLAYER_START_CHANNEL_REFUSALS.indexOf(str(code)) !== -1 ? "channel" : "local"
}

// Who a reply is about. Both `rememberEntry` call sites passed the shell's
// `nowPlaying`, which in a burst is the intent current when the REPLY
// landed, not the one the reply is for - which is precisely the case the
// entry-owner ring was built for (4.8). The consequence was a "Stream
// failed" toast naming a channel that never failed.
//
// `playing` is the `player start` stand-down's own field: when the helper
// leaves a newer channel alone, the entry on the player belongs to THAT
// channel, not to the one this verb was asked for.
function replyTarget(status, nowPlaying) {
  var doc = status && typeof status === "object" ? status : {}
  var left = doc.playing && typeof doc.playing === "object" ? doc.playing : null
  if (left && str(left.id) !== "") return { id: str(left.id), name: str(left.name) }
  if (str(doc.id) !== "") return { id: str(doc.id), name: str(doc.name) }
  if (nowPlaying && str(nowPlaying.id) !== "") return { id: str(nowPlaying.id), name: str(nowPlaying.name) }
  return null
}

// The shell's label against the player's own record, once a health tick can
// finally ask for it (`status` carries `stash`). Ruling CL5: the shell is
// authoritative and the repair is to RE-APPLY the user's intent, never to
// relabel from the player - relabelling would leave the user watching a
// channel they did not choose while the interface agreed with the mistake.
//
//   agree     the player's record names what the shell wants
//   unknown   nothing to compare: no record, no intent, or a record from a
//             different playlist whose ids mean something else. Never a
//             verdict, so an old helper or a foreign player raises nothing
//   diverged  they name different channels. `repair` is the id to re-apply
function reconcileVerdict(stash, nowPlaying, sourceKey) {
  var np = nowPlaying && str(nowPlaying.id) !== "" ? nowPlaying : null
  var record = playerStash(stash)
  var unknown = { state: "unknown", repair: "", wanted: np ? str(np.id) : "", playing: record ? record.id : "" }
  if (!np || !record || record.playing === false) return unknown
  var active = str(sourceKey)
  if (active !== "" && record.sourceKey !== "" && record.sourceKey !== active) return unknown
  if (record.id === str(np.id)) return { state: "agree", repair: "", wanted: str(np.id), playing: record.id }
  return { state: "diverged", repair: str(np.id), wanted: str(np.id), playing: record.id }
}

// The same question asked of a `player start` / `player restart` reply,
// which answers it directly: the helper says which channel it left on the
// player. "" means nothing to do; anything else is the id to re-apply.
function sessionIntentRepair(status, nowPlaying) {
  var left = replyTarget(status, null)
  var np = nowPlaying && str(nowPlaying.id) !== "" ? str(nowPlaying.id) : ""
  if (np === "" || !left || left.id === "") return ""
  return left.id === np ? "" : np
}

// ---- D-PLY-64: which Service instance holds the owner claim (4.14) ----
//
// The owner claim named the SHELL (pid and start time), and Omarchy 4.5.0's
// migrations showed the shell is not the unit that dies: they replaced
// shell.json for a moment, the host read its defaults, destroyed the plugin's
// Service and created a new one inside the same shell process. The new one's
// probe re-claimed the player with the same pid and start time; the old one's
// orphan check, six seconds later, read the claim as still its own with its
// shell alive -- "the plugin was disabled" -- and stopped the channel.
//
// So each Service object draws one token when it is created (Service.qml's
// `ownerToken`) and passes it on every verb that writes the claim (probe,
// start, restart) and on its orphan check, which reads a claim carrying any
// other token as reassigned. `--owner-token` is one of helperSpawn's private
// options, so on the verbs Service.runHelper starts it travels in
// OMARCHY_IPTV_ARGS; the orphan check alone carries it on its argv, because
// it is launched detached from a destruction handler and execDetached's
// command list is the only form measured to start there (an object is
// refused, Service.qml). Not a secret either way: it authorizes nothing,
// anything that can reach the player's socket reads the claim, and it names
// nothing outside the user's own 0700 runtime directory. 32 lowercase hex
// digits, four 32-bit draws: unrelated to anything, and two instances of one
// shell share one only by a 128-bit coincidence (QV4's Math.random reads
// Qt's global generator, QRandomGenerator::global, a Mersenne Twister
// securely seeded from the system generator). Measured under
// Qt 6.12's own engine (offscreen, 2026-11-06): the property Service.qml
// declares reads the same token across fifty changes to its object, and a
// hundred objects drew a hundred tokens. `draw` is the random source,
// Math.random unless a test hands one in (as randomSourceKey's). The
// helper's is_owner_token is the mirror, held to this one by the shared
// owner-token fixture (dev branch); a token this does not accept is never
// passed, so the claim then names the shell only, which is the rule as it
// was.
var OWNER_TOKEN_RE = /^[0-9a-f]{32}$/

function isOwnerToken(token) {
  return typeof token === "string" && OWNER_TOKEN_RE.test(token)
}

function playerOwnerToken(draw) {
  var d = typeof draw === "function" ? draw : Math.random
  var out = ""
  for (var i = 0; i < 4; i++) {
    var n = Math.floor(Number(d()) * 4294967296)
    if (!isFinite(n) || n < 0) n = 0
    var hex = (n % 4294967296).toString(16)
    while (hex.length < 8) hex = "0" + hex
    out += hex
  }
  return out
}

// `--owner-token <token>` for a verb that names an owner pid; nothing for a
// token isOwnerToken refuses.
function ownerTokenArgv(ownerToken) {
  return isOwnerToken(ownerToken) ? ["--owner-token", ownerToken] : []
}

function playerOrphanCheckArgv(socket, ownerPid, graceSec, ownerToken) {
  var pid = Math.floor(Number(ownerPid))
  var grace = Number(graceSec)
  if (!isFinite(grace) || grace <= 0) grace = PLAYER_ORPHAN_GRACE_SEC
  var owned = isFinite(pid) && pid > 0
  return ["player", "orphan-check", "--socket", str(socket),
          "--owner-pid", String(owned ? pid : 0)]
    .concat(owned ? ownerTokenArgv(ownerToken) : [])
    .concat(["--grace", String(grace)])
}

// The now-playing record that lives inside the mpv process, never on disk
// (4.6). `launchedFrom` is the zap-ring scope: pure UI intent that no mpv
// property could report, which is why the shell's own value is stashed and
// echoed back on reattach. Written by the helper, read back by
// `parsePlayerProbe`; this function is the shape of record for both sides.
function playerStash(params) {
  var p = params || {}
  var id = str(p.id)
  if (id === "") return null
  var entry = Math.floor(Number(p.entryId))
  var since = Math.floor(Number(p.since))
  return {
    schema: PLAYER_STASH_SCHEMA,
    playing: p.playing !== false,
    id: id,
    name: str(p.name),
    group: str(p.group),
    launchedFrom: str(p.launchedFrom),
    sourceKey: str(p.sourceKey),
    since: isFinite(since) && since > 0 ? since : 0,
    entryId: isFinite(entry) && entry > 0 ? entry : null,
    seq: Math.max(0, Math.floor(Number(p.seq)) || 0),
    // Which slot wrote the record last. It exists because `seq` stopped
    // being able to say so: the zap used to hardcode 0, and "not zero"
    // therefore meant "a player verb wrote this". Both sides now carry a
    // real intent number, which is what makes them comparable, so the
    // writer is named instead of inferred.
    verb: str(p.verb)
  }
}

function playerOwner(raw) {
  if (!raw || typeof raw !== "object") return null
  var pid = Math.floor(Number(raw.pid))
  if (!isFinite(pid) || pid <= 0) return null
  return { schema: PLAYER_STASH_SCHEMA, pid: pid, startTime: str(raw.startTime), at: Math.max(0, Math.floor(Number(raw.at)) || 0) }
}

// ---- D-SINK-16: is an adopted player safe to feed? ------------------------
//
// Raised by the marketplace maintainer against the SHIPPED 0.13.0 (#10389),
// hours after it was published, and he is sharper than our own D-PLY-25, which
// called this stale state a user could restart away: the plugin goes on sending
// NEW provider headers and NEW credentialed URLs into the unverified process,
// so it is an exposure we keep FEEDING, not one that merely lingers.
//
// Two readings decide it, taken over IPC by the helper (`migrate_tls`) AFTER it
// has tried to set them, because a `success` reply is not evidence of a value:
//   verify       mpv's `tls-verify`, and strictly the boolean true
//   optionCount  how many entries `stream-lavf-o` holds. FFmpeg's own
//                `tls_verify` AVOption reaches the same place as mpv's option
//                and outvotes it (D-SINK-13's layer 3), so a non-empty map is
//                not safe whatever is in it; cleared means 0.
//
//   unpinned     (2026-10-29, D-SINK-43/44) how many of the OTHER TLS pins the
//                player does not hold, summed by the helper: demuxer-lavf-o's
//                TLS entries (for HLS and DASH they configure the protocol of
//                every segment open), load-auto-profiles not reading off (a
//                profile-cond profile applies over the command line at every
//                load), and the user's [protocol.*] / [extension.*] profiles
//                that could undo, at file load, an option this player does not
//                have set from the command line. A player launched with the
//                pin block reads 0; one launched by 0.15.0 or earlier is
//                migrated where it can be, and a per-file profile no migration
//                can reach leaves it unsafe -- stopped, not fed.
//
// COUNTS and never the keys or the values: `stream-lavf-o` can hold a proxy
// address with credentials in it, and these numbers cross a process boundary
// into the shell, which is a rule 5 sink like any other. The counts are the
// whole of what the decision needs.
//
// Mirror of tls_properties_safe in the helper; both sides run the shared
// player-tls.json fixture (dev branch).
function tlsPropertiesSafe(verify, optionCount, unpinned) {
  if (verify !== true) return false
  var counts = [optionCount, unpinned]
  for (var i = 0; i < counts.length; i++) {
    if (!(typeof counts[i] === "number" && isFinite(counts[i]) && counts[i] === 0)) return false
  }
  return true
}

// The two readings, as the probe reply carries them. Defensive in the same way
// playerStash and playerOwner are: a helper that dropped or renamed the node
// must not read as SAFE by accident, so `verify` is three-valued and anything
// that is not a number leaves `optionCount` null - and tlsPropertiesSafe()
// refuses null. `false` for a count would otherwise coerce to 0 and pass.
function playerTls(raw) {
  if (!raw || typeof raw !== "object") return null
  return {
    verify: raw.verify === true ? true : (raw.verify === false ? false : null),
    // A WHOLE count, not a rounded one: the helper produces it with len() on a
    // map, so a fraction is not a small reading, it is a reading from something
    // that is not the helper -- and Math.floor() would turn 0.5 into the one
    // value that passes.
    optionCount: wholeCount(raw.optionCount),
    // The same shape for the third reading; absent (a helper older than the
    // pin block cannot answer a shell newer than it, but a renamed field can)
    // reads null, which the verdict refuses.
    unpinned: wholeCount(raw.unpinned),
    migrated: raw.migrated === true
  }
}

function wholeCount(count) {
  return typeof count === "number" && isFinite(count) && count >= 0 && Math.floor(count) === count ? count : null
}

// What the reattach path does with the player it has just identified:
//
//   "feed"   it was already verifying and nothing is owed: this shell launched
//            it, or an earlier probe migrated it and a load of this build has
//            since re-established its channel (D-SINK-72: that load spends the
//            mark). Adopt it, nothing else to do.
//   "reload" it was NOT, the helper has made it verify, and the channel must be
//            re-established before anything else is sent to it. Setting the
//            property covers the NEXT load; whether an already-open stream
//            picks the change up for its ongoing segment fetches is UNMEASURED,
//            so the reload is what makes the answer not matter.
//   "stop"   the properties could not be made safe, or there are no readings at
//            all. Then the player is stopped rather than fed, because feeding
//            it is precisely the act of handing a credentialed URL and the
//            provider headers to a process we could not secure.
//
// `migrated` is the helper's answer to "has a probe had to change this
// player's TLS settings since a load of this build last re-established its
// channel". D-SINK-72: the migrating probe leaves a mark on the player, and
// every later probe reports it until apply_channel's load clears it, so a
// second probe before the reload answers "reload" again and one after it
// answers "feed": the rebuffer is paid once. The caller still only ever SETS
// its pending-reload flag from this, never clears it, because a mark mpv
// refused leaves a later probe -- the 500 ms retry of an ambiguous first
// probe (idle, or no stash yet) among them -- reading nothing left to do.
// D-SINK-16. What to do with an owed TLS re-establish, as a function rather
// than as three conditions in a row, because the first version got one of them
// wrong in a way no test could see: it CLEARED the flag whenever `nowPlaying`
// was null, and null there is two different things. "The user stopped" means
// nothing is owed any more. "Not assigned yet" is the reattach-after-upgrade
// moment itself -- the flag is set before nowPlaying is -- and clearing it
// there drops the reload for good, because it is armed in exactly one place.
// The already-open unverified stream then runs to the end of its stream, which
// is the exposure this whole round is about. Found by the review of the lane
// that wrote it.
//
//   "clear"   nothing is owed: the user's own stop ended it
//   "hold"    owed, but the shell is not ready to deliver it yet
//   "deliver" owed and deliverable now
//
// D-PLY-51 (2026-11-01): and "clear" when the channel cannot be put back on
// THIS shell's list -- the stash is another source's, or the applied list no
// longer holds the id. The reload re-sends the id against the ACTIVE source's
// cache (zapArgs), so with the source switched while the shell was down it
// played the active source's channel of the same id; reconcileNowPlaying has
// always refused that stash. Nothing is delivered: the player plays on, and
// every load it is later fed goes through apply_channel's own assertion. It
// waits for the channel LIST, not only the cache folder, for the same reason.
// The question is adoptedChannelReach's, which the restart of a player
// another build launched asks too (olderRestartDisposition).
function tlsReloadDisposition(o) {
  var s = o || {}
  if (s.pending !== true) return "none"
  if (s.stopping === true || s.userStopped === true) return "clear"
  var reach = adoptedChannelReach({ nowPlayingId: s.nowPlayingId, channelsLoaded: s.channelsLoaded === true && !!s.cacheDir,
                                    hasChannel: s.hasChannel, sourceMatches: s.sourceMatches, playerUp: s.playerUp })
  if (reach === "gone") return "clear"
  return reach === "ready" ? "deliver" : "hold"
}

// ---- restart on adoption (owner, 2026-10-31 and 2026-11-01) ----
//
// A player another build of this plugin launched -- another release, another
// helper build (the probe's `launch`, the helper's launch_verdict) -- is
// replaced, never fed. The shell's half: on reattach it adopts such a player
// for a HOLD (the bar shows the stash at once), waits for the channel list,
// and then issues one `player start --keep-pause` of the same channel, which
// the helper turns into "read the carry, ladder the old one, spawn, load".
// Every rule below is one of design.md 4.2's rows (scratchpad), settled by
// the owner's answers: a paused player comes back paused (Q3), a restart
// that cannot be delivered plays on fed nothing and is replaced at the next
// channel change (Q4), except a player that cannot be made safe and a
// channel this build refuses, which stop; silent on success but for one
// fixed journal line (Q5).

// The one journal line of an automatic restart (the frozen interface): fixed
// text -- no channel name, no id, no pid list, no argv element (rule 5).
var OLDER_RESTART_LINE = "omarchy-iptv: restarting a player another build of this plugin started, on the channel it was playing"
// And the line when a player THIS shell's own restart started reads as
// another build's again: the restart is not repeated (design 4.4.3), so a
// builder/reader disagreement shows itself instead of looping.
var OLDER_RESTART_AGAIN_LINE = "omarchy-iptv: a player this plugin restarted does not read as this build's; leaving it playing"
// The hold: how long the adopted player plays on while the channel list is
// applied, before the restart is deferred (or the player stopped when it
// cannot be made safe). M6, in the cage, sizes it.
var OLDER_RESTART_HOLD_MS = 15000

// The probe's word that asks for a restart: another build's player, or one
// that is not ours to judge at all. null (a helper too old to say) is not.
function probeLaunchOlder(launch) {
  return launch === "older" || launch === "unknown"
}

// reconcileNowPlaying's test, as a function: a stash from another source is
// never resolved against this one. "" on either side matches (a stash from
// before source keys, a shell with no source yet).
function adoptedSourceMatches(playerSourceKey, activeSourceKey) {
  var p = str(playerSourceKey)
  var a = str(activeSourceKey)
  return !(p !== "" && a !== "" && p !== a)
}

// Whether the channel an ADOPTED player is streaming can be put back on this
// shell's channel list (D-PLY-51; the restart's re-resolution, design 4.5):
//   "hold"   not yet: no id assigned, or the list not applied
//   "gone"   never: the stash is another source's, or the list lacks the id
//   "busy"   the list holds it, but the player is not up or the slot is busy
//   "ready"  deliverable now
function adoptedChannelReach(o) {
  var s = o || {}
  if (s.nowPlayingId === null || s.nowPlayingId === undefined || str(s.nowPlayingId) === "") return "hold"
  if (s.channelsLoaded !== true) return "hold"
  if (s.sourceMatches !== true || s.hasChannel !== true) return "gone"
  if (s.playerUp !== true || s.slotBusy === true) return "busy"
  return "ready"
}

// What the shell does with an open restart episode (design 4.2):
//   "none"     no episode: the TLS reload's own rule applies (reestablishForTls)
//   "clear"    a stop: the episode ends
//   "hold"     not deliverable yet: the next call delivers
//   "restart"  issue the one automatic `player start --keep-pause`
//   "defer"    spent, or undeliverable (channel gone, another source, the hold
//              expired), and the player reads safe: it plays on, fed nothing,
//              and the user's next channel change replaces it (Q4)
//   "stop"     as defer, but the player could not be made safe: stopped, as
//              0.16.0 stops one (Q4's first exception)
// An unsafe player whose restart CAN be delivered is restarted, not stopped:
// the new player sets every pin from its own command line, which no
// [protocol.*] profile replaces (D-SINK-44), so the user keeps the channel.
//
// D-SINK-71 (owner, 2026-11-02, "replace late, when the list lands"): the
// hold's expiry does not defer a player the probe had to MIGRATE (`migrated`,
// the TLS reading's own word: its settings were changed in place, so the
// stream it already has open may have been opened without them -- every
// 0.15.0 player reads so). For it, "expired" keeps holding and the one
// automatic restart goes out whenever the list lands and the channel is
// deliverable; that restart is what the D-SINK-16 reload was for. (0.16.0's
// reload had no hold, but it never waited for the list either: it went out
// once the cache DIRECTORY was known, at the probe or the channel file's
// first load or load failure, and the helper resolved the id against the
// channels.json on disk -- so with no file there yet it failed and was spent;
// read in 202a7bc, rc-sk71.) Unchanged: a channel gone defers, an unsafe
// player still stops at the expiry (it cannot be delivered then and cannot
// be made safe), a player that read safe without migration still defers at
// the expiry, and a spent episode stays spent.
function olderRestartDisposition(o) {
  var s = o || {}
  if (s.owed !== true) return "none"
  if (s.stopping === true || s.userStopped === true) return "clear"
  if (s.spent === true) {
    if (s.slotBusy === true) return "hold"
    return s.unsafe === true ? "stop" : "defer"
  }
  var reach = adoptedChannelReach(s)
  if (reach === "ready") return "restart"
  if (reach === "gone") return s.unsafe === true ? "stop" : "defer"
  if (s.expired === true) {
    if (s.unsafe === true) return "stop"
    if (s.migrated !== true) return "defer"
  }
  return "hold"
}

// Whether a `player start` the shell issues now is the episode's own
// automatic restart -- issued, and no newer intent since -- and so keeps the
// old player's pause (`--keep-pause`). A retry of it keeps it; a user's
// channel change (play() moves playSeq) never does (PAUSE LIVE TV).
function olderRestartKeepsPause(episode, playSeq) {
  var e = episode && typeof episode === "object" ? episode : null
  return e !== null && e.spent === true && Math.floor(Number(e.seq)) === Math.floor(Number(playSeq))
}

// The episode record with some fields changed and every other one carried,
// whatever fields it has: each place that moves the episode (a channel
// change spending it, a deferral, the restart, the hold's end) rebuilds it
// through this, so none of them can drop a field a later reader needs --
// the player it was opened for above all (olderRestartOpen). null for no
// episode.
function olderRestartWith(episode, changes) {
  var e = episode && typeof episode === "object" ? episode : null
  if (e === null) return null
  var c = changes && typeof changes === "object" ? changes : {}
  var out = {}
  for (var k in e) if (Object.prototype.hasOwnProperty.call(e, k)) out[k] = e[k]
  for (var j in c) if (Object.prototype.hasOwnProperty.call(c, j)) out[j] = c[j]
  return out
}

// D-SINK-73 (2026-11-02): which player an episode was opened for, from what
// the reattach probe tells the shell -- the process its connection reached
// (`pid`) and the stash that process carries: the channel's id and source,
// the time it started playing and the entry it loaded. A player another
// build launched is fed nothing, so none of these moves while it is the same
// process. Not the episode's `seq`: that is this shell's intent counter, which
// says whether the shell has acted since, not which process answered -- the
// same player answers after a user's start the watchdog stopped (path 6, the
// counter moved), and a different one can answer while it stands still. A
// pid the probe did not name is 0 and compares on the stash alone; no stash
// is no identity (the probe never adopts a player without one).
function olderPlayerIdentity(pid, stash) {
  var s = stash && typeof stash === "object" ? stash : null
  if (s === null || str(s.id) === "") return null
  var p = Math.floor(Number(pid))
  var since = Math.floor(Number(s.since))
  var entry = Math.floor(Number(s.entryId))
  return { pid: isFinite(p) && p > 0 ? p : 0, id: str(s.id), sourceKey: str(s.sourceKey),
           since: isFinite(since) && since > 0 ? since : 0, entryId: isFinite(entry) && entry > 0 ? entry : 0 }
}

function sameOlderPlayer(a, b) {
  var x = a && typeof a === "object" ? a : null
  var y = b && typeof b === "object" ? b : null
  if (x === null || y === null) return false
  if (x.id !== y.id || x.sourceKey !== y.sourceKey || x.since !== y.since || x.entryId !== y.entryId) return false
  return x.pid === 0 || y.pid === 0 || x.pid === y.pid
}

// D-SINK-73: what a probe that finds a player another build launched does
// to the restart episode. The shell probes a player it is already holding
// when its own connect fails while the helper's succeeds (the socket hunt's
// probe after its burst; a `recover` runs only after a start's ok reply has
// ended the episode), and every such probe used to open the
// episode afresh: unspent, unexpired, the hold re-armed. So a DEFERRED
// player got the automatic restart after all, against the design's `defer`
// for a spent episode and "one automatic restart per shell start"
// (ARCHITECTURE-PLAYER 4.5.2), and an UNSAFE one's
// stop at the hold's end moved 15 s later with every probe (rc-sk71's
// probes E and F).
//
// The SAME player (sameOlderPlayer) keeps its open episode: spent, expired
// and the intent it was issued under stay as they were, and the hold is not
// re-armed (`armHold` false), so it ends when it was going to. `migrated`
// is kept too (D-SINK-71: a later probe normally reads it again from the
// player's mark, D-SINK-72; where mpv refused the mark, or the mark could
// not be read, that probe finds nothing left to migrate), and
// `unsafe` is this probe's reading, as before: an unsafe one is stopped at
// once if the episode is spent; otherwise it is restarted if its channel
// becomes deliverable before the hold ends, and stopped at the hold's end
// if not. A DIFFERENT
// player -- the old one gone, another answering, or the same one read under
// another pid -- opens its own episode, inheriting none of the old one's
// spent, expiry or intent; it carries `migrated` (rc-sk73, below). A start
// the watchdog stopped whose probe finds the older player (path 6) spends the
// episode either way: that start's failure is told once, by the caller,
// whichever branch this takes ("while path 6's card is still raised",
// rc-sk71).
//   current   the open episode, or null
//   o         { seq, pid, stash, unsafe, migrated, timedOut, delivered }:
//             the shell's intent counter, the probe's pid and stash, its TLS
//             reading, whether a stopped start is being settled, and whether
//             this shell already restarted a player another build launched
// -> { episode, armHold, again }: the record to hold; whether to start the
// hold; whether to journal OLDER_RESTART_AGAIN_LINE (a new episode on a
// player this shell's own restart started, design 4.4.3 -- once per episode,
// not once per probe).
function olderRestartOpen(current, o) {
  var s = o || {}
  var cur = current && typeof current === "object" ? current : null
  var player = olderPlayerIdentity(s.pid, s.stash)
  var timedOut = s.timedOut === true
  if (cur !== null && sameOlderPlayer(cur.player, player)) {
    return { episode: olderRestartWith(cur, { unsafe: s.unsafe === true, spent: cur.spent === true || timedOut,
                                              migrated: cur.migrated === true || s.migrated === true }),
             armHold: false, again: false }
  }
  var again = !timedOut && s.delivered === true
  var spent = timedOut || again
  // rc-sk73: `migrated` is carried from ANY open episode, as it was before
  // the identity existed (D-SINK-71). The same player can be read under
  // another pid -- behind a wrapper that runs mpv as its child both carry
  // the socket's argument, and when mpv's own pid read fails the probe names
  // the lower one. That probe reads the player's mark and answers `migrated`
  // itself (D-SINK-72). Where mpv refused the mark, it finds nothing left to
  // migrate, and taking its reading alone would let the hold's end defer a
  // player whose open stream predates the migration (as it did on d6a23dc,
  // before the mark). A different player that takes it costs at most one
  // restart when its list lands late.
  var carried = cur !== null && cur.migrated === true
  return { episode: { seq: Math.floor(Number(s.seq)) || 0, unsafe: s.unsafe === true, spent: spent, expired: false,
                      migrated: s.migrated === true || carried, player: player },
           armHold: !spent, again: again }
}

function playerTlsVerdict(tls) {
  var reading = playerTls(tls)
  if (reading === null) return { safe: false, action: "stop", migrated: false }
  if (!tlsPropertiesSafe(reading.verify, reading.optionCount, reading.unpinned)) {
    return { safe: false, action: "stop", migrated: reading.migrated }
  }
  return { safe: true, action: reading.migrated ? "reload" : "feed", migrated: reading.migrated }
}

// `player probe` stdout -> a shape the service can bind. Garbage, a truncated
// line, a foreign JSON document or an error reply all return valid:false
// rather than throwing, so a probe can never break the reattach path.
// Restart on adoption (2026-11-01): the helper's one-word answer to "was the
// player this probe reached launched by THIS build" (launch_verdict). The
// three words it can say; anything else -- absent from a helper too old to
// say it (D-REL-9's new-QML / old-helper window), a renamed node, garbage --
// is null, which the shell reads as today's path, unchanged.
var PLAYER_LAUNCH_WORDS = ["current", "older", "unknown"]

function playerLaunch(raw) {
  return typeof raw === "string" && PLAYER_LAUNCH_WORDS.indexOf(raw) !== -1 ? raw : null
}

function parsePlayerProbe(text) {
  var empty = { valid: false, running: false, responsive: false, pid: null, idle: null, stash: null, owner: null, seq: 0, rewind: null, tls: null, launch: null }
  var doc = parseJsonObject(text)
  if (!doc || doc.ok !== true || str(doc.kind) !== "player.probe") return empty
  var pid = Math.floor(Number(doc.pid))
  return {
    valid: true,
    running: doc.running === true,
    responsive: doc.responsive === true,
    pid: isFinite(pid) && pid > 0 ? pid : null,
    idle: doc.idle === null || doc.idle === undefined ? null : doc.idle === true,
    stash: playerStash(doc.stash),
    owner: playerOwner(doc.owner),
    seq: Math.max(0, Math.floor(Number(doc.seq)) || 0),
    // M5-01: the reattach read recovers "behind live" from the player.
    rewind: parseRewind(doc.rewind),
    // D-SINK-16: the two TLS readings of the player this shell is about to
    // adopt. Absent reads null, which playerTlsVerdict answers "stop" to - an
    // adopted player whose certificate handling cannot be established is not a
    // player to feed.
    tls: playerTls(doc.tls),
    // Restart on adoption: current, older, unknown or null (playerLaunch).
    launch: playerLaunch(doc.launch)
  }
}

// One newline-delimited line from mpv's own JSON IPC socket (4.8). Only the
// four event kinds the service acts on are recognised; a command reply, an
// unknown event, junk and a truncated line are all `{kind:"ignored"}`.
// `log-message` text is redacted a second time here: the helper redacts it
// on its own path, but this line comes straight off the socket.
function parsePlayerEvent(line) {
  var ignored = { kind: "ignored" }
  var doc = parseJsonObject(line)
  if (!doc) return ignored
  var event = str(doc.event)
  if (event === "start-file") {
    return { kind: "start-file", entryId: playerEntryId(doc.playlist_entry_id) }
  }
  if (event === "end-file") {
    return { kind: "end-file", entryId: playerEntryId(doc.playlist_entry_id), reason: str(doc.reason), fileError: str(doc.file_error) }
  }
  if (event === "log-message") {
    return { kind: "log-message", level: str(doc.level), prefix: str(doc.prefix), text: trimEndSpace(redactUrls(str(doc.text))) }
  }
  if (event === "property-change" && str(doc.name) === "idle-active") {
    return { kind: "property-change", name: "idle-active", value: doc.data === true }
  }
  return ignored
}

function playerEntryId(value) {
  var n = Math.floor(Number(value))
  return isFinite(n) && n > 0 ? n : null
}

// Why the player ended (4.8), replacing the exit code `mpvProc.onExited` gave.
// The entry gate FAILS OPEN (F4): the entry id decides which channel the
// toast names, never whether there is a toast, so a `playlist_entry_id` that
// is missing or unknown can never suppress a failure the user can see.
function endedVerdict(lastEndFile, userStopped, stopping) {
  if (userStopped === true || stopping === true) return { notify: false, reason: "", kind: "silent" }
  var end = lastEndFile && typeof lastEndFile === "object" ? lastEndFile : null
  if (!end) return { notify: true, reason: PLAYER_GENERIC_FAILURE, kind: "failed" }
  var reason = str(end.reason)
  // An intermediate .m3u8 master resolution: never terminal, never a verdict.
  if (reason === "redirect") return { notify: false, reason: "", kind: "ignored" }
  if (reason === "quit" || reason === "eof") return { notify: false, reason: "", kind: "silent" }
  var detail = redactUrls(str(end.fileError || end.file_error)).trim()
  return { notify: true, reason: detail !== "" ? detail : PLAYER_GENERIC_FAILURE, kind: "failed" }
}

// What survives a `player probe` reply (4.10, and section 15's race).
//
// A probe answers about the world it was ISSUED into. The startup probe goes
// out from Component.onCompleted and answers about 130 ms later, and a play
// can arrive inside that window - from the guide, or over IPC one frame
// after the shell came back. Its "nothing is running" then cleared
// nowPlaying and playerWanted, and drainPendingPlay(), which needs a
// nowPlaying, dropped the queued play on the floor.
//
// The sequence resync is the one part of a stale reply that is still true,
// and it MOVES the counter staleness is measured against - so both answers
// come from one call rather than from two lines a caller can order wrongly.
// (They were: reading staleness after the resync makes every startup probe
// look stale, which silently disables PO-3's mark.)
function probeVerdict(recordedSeq, issuedAt, currentSeq) {
  var recorded = Math.floor(Number(recordedSeq)) || 0
  var current = Math.floor(Number(currentSeq)) || 0
  return { seq: Math.max(current, recorded + 1), stale: current !== (Math.floor(Number(issuedAt)) || 0) }
}

// What a socket EOF means, which is not always "the player ended" (4.8
// signal 3). `player start` and `player restart` ladder a player DOWN and
// spawn its replacement inside one helper call, so the death of the player
// they are replacing arrives here while that very call is still in flight -
// a rung of our own respawn, not an unattended end.
//
// Reading it as an end is the reported P1: the shell cleared `nowPlaying`
// and `playerWanted`, the helper's success reply then read the cleared
// `nowPlaying` as "a stop overtook this start" and declined to re-arm the
// observer, and with `wanted` false the 250 ms retry timer was off - so the
// interface sat idle forever while the freshly spawned player kept playing.
//
// Order matters: a stop we issued outranks everything (it is why the player
// is dying), then our own in-flight respawn, then the health verdict's
// queued relaunch, then the ending.
function playerDeathKind(context) {
  var ctx = context || {}
  if (ctx.userStopped === true || ctx.stopping === true) return "ended"
  if (ctx.nowPlaying !== true) return "ended"
  if (ctx.sessionInFlight === true) return "respawn"
  if (ctx.relaunchPending === true && ctx.hasChannel === true) return "relaunch"
  return "ended"
}

// What to do with the observer when `player start` / `player restart` answers
// ok. The helper has just reported a live player of this shell's making, so
// the one answer that is never right is to do nothing - that is the second
// half of the P1 above.
//
//   attached  the observer is already on it; only the birth edge to drop
//   abandoned a stop really did overtake this start; nothing to hunt
//   hunt      the player is up, the observer is not on it yet: arm and wait
//   recover   the same, and we no longer know WHAT is playing, so read it
//             back out of the player's own stash - the identical path a
//             shell restart takes (4.5), which is why it needs no new rule
function playerSessionFollowUp(context) {
  var ctx = context || {}
  if (ctx.attached === true) return "attached"
  if (ctx.stopping === true || ctx.userStopped === true) return "abandoned"
  return ctx.nowPlaying === true ? "hunt" : "recover"
}

// ---------------------------------------------------------------------
// The event router as pure logic (4.8).
//
// Service.qml owns the socket, the timers, the properties and the toast.
// What it must not own is the DECISION, because a decision that lives in a
// QML method can only be pinned by a copy of itself in the spec file, and a
// copy passes just as happily when the shipping path is broken - the same
// trap as a test double more forgiving than the real thing (engineering rule 10 (dev branch)).
// So handlePlayerLine(), rememberEntry(), channelForEnd() and the terminal
// half of handlePlayerGone() are these four functions plus assignments.

// The router's state between lines: which entry is loading, the last
// terminal end-file (null once a new load supersedes it), observed
// idle-active, and the five-line log tail.
function playerRouterState(state) {
  var st = state && typeof state === "object" ? state : {}
  return {
    entryId: playerEntryId(st.entryId) || 0,
    lastEndFile: st.lastEndFile || null,
    idle: st.idle === true,
    tail: asList(st.tail)
  }
}

// The log / stderr tail: error and fatal only, redacted (again - the helper
// redacts its own path, this line came straight off the socket), trailing
// whitespace stripped, five lines deep, memory only. Returns the SAME array
// when the line adds nothing, so a caller can skip the property write.
function pushPlayerLog(tail, line) {
  var rows = asList(tail)
  var clean = redactUrls(trimEndSpace(line))
  if (clean === "") return rows
  var out = rows.slice()
  out.push(clean)
  while (out.length > PLAYER_LOG_TAIL) out.shift()
  return out
}

// One newline-delimited line from mpv's socket applied to the router state.
// Always returns a full state object; unchanged fields keep their exact
// references (`tail`, `lastEndFile`), so the caller writes only what moved.
function routePlayerEvent(state, line) {
  var st = playerRouterState(state)
  var event = parsePlayerEvent(line)
  if (event.kind === "start-file") {
    // A new load supersedes the previous end: this is what makes a zap
    // (end-file{stop} then start-file) silent.
    return { entryId: event.entryId ? event.entryId : st.entryId, lastEndFile: null, idle: st.idle, tail: st.tail }
  }
  if (event.kind === "end-file") {
    return { entryId: st.entryId, lastEndFile: event, idle: st.idle, tail: st.tail }
  }
  if (event.kind === "log-message") {
    if (event.level !== "error" && event.level !== "fatal") return st
    var text = (event.prefix !== "" ? "[" + event.prefix + "] " : "") + event.text
    return { entryId: st.entryId, lastEndFile: st.lastEndFile, idle: st.idle, tail: pushPlayerLog(st.tail, text) }
  }
  if (event.kind === "property-change") {
    return { entryId: st.entryId, lastEndFile: st.lastEndFile, idle: event.value === true, tail: st.tail }
  }
  return st
}

// The entry-ownership ring: mpv's own playlist_entry_id -> the channel that
// load was for, so a failure that arrives after the user has zapped away
// still names the right row. At most four entries, oldest dropped. Returns
// the SAME map when there is nothing to record.
function rememberEntryOwner(owners, entryId, target) {
  var map = owners && typeof owners === "object" ? owners : {}
  var id = playerEntryId(entryId)
  if (id === null || !target) return map
  var out = keyedMap()
  var keys = Object.keys(map)
  for (var i = Math.max(0, keys.length - (PLAYER_ENTRY_OWNERS - 1)); i < keys.length; i++) out[keys[i]] = map[keys[i]]
  out[String(id)] = { id: str(target.id), name: str(target.name) }
  return out
}

// Which channel a load belonged to. The gate FAILS OPEN (F4): an unknown,
// missing or non-numeric entry id degrades to whatever is playing now and
// can never suppress a failure the user must see.
function channelForEnd(owners, end, current) {
  var map = owners && typeof owners === "object" ? owners : {}
  if (end && end.entryId) {
    var owner = ownKeyValue(map, String(end.entryId))
    if (owner) return owner
  }
  return current ? { id: str(current.id), name: str(current.name) } : null
}

// The terminal decision at socket EOF (4.8 signal 3): whether the user hears
// about this death, which channel it names, and with what text. The log tail
// outranks mpv's own generic `file_error` ("loading failed" says nothing;
// "[stream] Failed to open provider.test" says what happened).
function endedReport(context) {
  var ctx = context && typeof context === "object" ? context : {}
  var verdict = endedVerdict(ctx.lastEndFile, ctx.userStopped === true, ctx.stopping === true)
  var tail = asList(ctx.tail)
  var format = unopenedFormatSentence(ctx.lastEndFile)
  return {
    notify: verdict.notify === true,
    kind: verdict.kind,
    target: channelForEnd(ctx.owners, ctx.lastEndFile, ctx.nowPlaying),
    reason: format !== "" ? format : tail.length > 0 ? playerTailReason(tail) : str(verdict.reason)
  }
}

// D-PLY-29: a log or stderr line that only WARNS is not the reason a channel
// did not play. Under software GL, mpv's stderr carries driver lines such as
// "MESA-EGL: warning: failed to get driver name for fd -1", and the tail's
// last line used to be the reason whatever it said. A line is a warning when
// it opens, after an optional "[prefix] " and any run of "tag: " words, with
// "warning:" in one of three spellings. Exact cases, no case-insensitive
// flag: the helper's player_log_warning is the same pattern, and the two
// languages fold case differently outside ASCII. Pinned in the shared
// fixture player-endings.json (`warningLines`), which the python suite reads.
var PLAYER_WARNING_RE = /^(?:\[[^\]]*\] )?(?:[A-Za-z0-9_.-]+: )*(?:warning|Warning|WARNING):/

function playerLogWarning(line) {
  return PLAYER_WARNING_RE.test(str(line))
}

// The reason a tail gives: its last line that is not a warning, or its last
// line when every line warns (a warning still says more than nothing). ""
// for an empty tail.
function playerTailReason(tail) {
  var rows = asList(tail)
  for (var i = rows.length - 1; i >= 0; i--) if (!playerLogWarning(rows[i])) return str(rows[i])
  return rows.length > 0 ? str(rows[rows.length - 1]) : ""
}

// D-PLY-44 (owner, 2026-10-29: refuse nested playlists). The helper's own
// loadfile carries the per-file option `demuxer=lavf`, so a stream server
// that answers with a plain playlist -- and a channel whose address is itself
// a .m3u or .pls redirector -- is not opened. mpv ends that load with reason
// "error" and this `file_error` (its MPV_ERROR_UNKNOWN_FORMAT), after one
// error-level line, "[cplayer] Failed to recognize file format." (measured on
// mpv 0.41.0 for a .pls, a plain .m3u and a web page, windowless, lane-p1b
// 2026-10-29). That line says nothing a user can act on, so this sentence
// outranks the log tail for that ending, and only for it. It names both
// things the ending can mean, because mpv cannot tell them apart: a
// playlist file, which the player no longer opens, and a page, which it
// never did. Pinned in the shared fixture player-endings.json
// (`formatErrors`), which the python suite reads too.
var PLAYER_FORMAT_ERROR = "unrecognized file format"
var PLAYER_FORMAT_SENTENCE = "The address sent a playlist file or a web page, which the player does not open"

// The sentence for an end-file that says mpv could not tell what the stream
// is, "" for any other ending. Exact string after a trim, as outputFailure.
function unopenedFormatSentence(end) {
  if (!end || typeof end !== "object" || str(end.reason) !== "error") return ""
  var raw = end.fileError !== undefined && end.fileError !== null && str(end.fileError) !== "" ? end.fileError : end.file_error
  return str(raw).trim() === PLAYER_FORMAT_ERROR ? PLAYER_FORMAT_SENTENCE : ""
}

// D-PLY-37 (owner, 2026-10-28): an OUTPUT of this machine that could not be
// opened is this machine's failure, not the stream's. mpv ends the file with
// reason "error" and one of these `file_error` strings -- the names of mpv's
// own MPV_ERROR_AO_INIT_FAILED and MPV_ERROR_VO_INIT_FAILED -- and the join is
// on mpv's prose, so the strings are pinned in the shared fixture
// player-endings.json (dev branch tests) with the version they were read
// from, and a python test runs the real mpv to see the audio one again (a
// later mpv that reworded it turns that test red, not a channel). Measured on mpv 0.41.0
// (2026-10-28, windowless and silent): an ALSA device that does not exist,
// PulseAudio down and PipeWire down each play the picture on and end the file
// with "audio output initialization failed", once the file ends. The video
// one is in mpv's error table and was reached by none of the five video
// output failures measured: a per-file one reads "no audio or video data
// played" when nothing else can play (and marks, as a stream with nothing
// playable does), or nothing at all when the sound plays on, and the
// player's own --force-window=immediate makes a video output that cannot
// open an exit before the socket, which has no end-file (D-PLY-27). It is
// kept on the owner's word and is UNVERIFIED.
var PLAYER_OUTPUT_ERRORS = [
  ["audio output initialization failed", "audio"],
  ["video output initialization failed", "video"]
]

// "audio" or "video" when an end-file says an output of this machine could
// not be opened, "" for anything else. Exact strings, compared after a trim:
// a near match is mpv saying something else.
function outputFailure(end) {
  if (!end || typeof end !== "object" || str(end.reason) !== "error") return ""
  var raw = end.fileError !== undefined && end.fileError !== null && str(end.fileError) !== "" ? end.fileError : end.file_error
  var detail = str(raw).trim()
  for (var i = 0; i < PLAYER_OUTPUT_ERRORS.length; i++) if (detail === PLAYER_OUTPUT_ERRORS[i][0]) return PLAYER_OUTPUT_ERRORS[i][1]
  return ""
}

// The sentence lastError records and the card carries for a lost output.
function outputFailureSentence(output) {
  if (output === "video") return "This computer's video output could not be opened"
  if (output === "audio") return "This computer's audio output could not be opened"
  return ""
}

// D-PLY-33 (owner, 2026-10-28): what a player's death says about the CHANNEL.
// endedReport answers whether the user hears about a death and which channel
// it names; this answers what the death is evidence of, for every detector
// that sees one. The owner's rule: a channel is marked failed only when mpv
// said the stream failed to load -- an end-file whose reason is "error", for
// that channel's own entry. Every other death the user is told about -- a
// crash, an external or out-of-memory kill, a VO abort (D-PLY-27), a load
// replaced and then a death ("stop") -- is told (F4 fails open) and marks
// nothing, under copy that neither blames the stream nor says "did not play"
// about a channel that may have played for an hour (PO-4). Until this, 4.8's
// table read "no end-file at all" as a stream failure, and no code could
// tell a death on this machine's account from one a stream caused.
//
// D-PLY-37 (owner, 2026-10-28): an end-file error that names an OUTPUT of
// this machine (outputFailure above) is not the stream failing to load: told
// as "outputFailed", in copy that blames this computer, and marked never --
// whichever entry it names, because the cause is known either way.
//
// "Own entry": the end-file names an entry, and either the entry-owner ring
// says whose it is (channelForEnd names that owner), or the ring has not
// heard of it and it is the entry the player last started (the router's
// entryId, from start-file). The second half is not a loosening: the reply
// that puts an entry on the ring can land after mpv has failed that load and
// quit (apply_channel says so of an instant failure), and the ring alone
// would leave a dead stream on a warm player unmarked. An error for an entry
// neither names, or with no entry id, is no evidence about the channel the
// card names, so it is told and not marked.
//
// The detectors (Service.qml):
//   the socket's EOF  context.lastEndFile, owners, nowPlaying, entryId,
//                     userStopped, stopping, tail -- handlePlayerGone
//   context.unattended  PO-3's reattach: the player died with no shell
//                     attached, so no end-file was seen by anyone. Never told
//                     (PO-3) and, by the same rule, never marked.
//   context.firstLoad `player start`'s own first-load window answered
//                     "failed" (context.reason, its reason). D-PLY-36: the
//                     reply now says which ending it saw, in
//                     context.ended -- "end-file" (mpv sent an end-file error
//                     for the start's entry; its file_error in
//                     context.fileError) or "closed" (mpv closed the
//                     connection: it died, with no end-file). An end-file
//                     error is the stream's -- marked, "Stream failed" --
//                     unless it names an output (D-PLY-37); a closed
//                     connection is a death with no end-file, told as
//                     "Playback stopped" and never marked. A reply without the
//                     field (a helper from before D-PLY-36) is the helper's
//                     word, taken as it always was: marked, "Stream failed".
//
// Returns { notify, mark, card, target, reason, output }: card is the
// notifyArgv event ("streamFailed", "playerStopped" or "outputFailed"), ""
// when nothing is told; reason is what lastError records -- endedReport's
// tail-or-file_error for a load that failed (D-PLY-29 stands there), the
// generic sentence for a death with no such end-file, whose card carries no
// reason at all, and the output's sentence for an output that could not be
// opened; output is "audio" or "video" for that card, "" otherwise.
function deathReport(context) {
  var ctx = context && typeof context === "object" ? context : {}
  if (ctx.unattended === true) return { notify: false, mark: false, card: "", target: null, reason: "", output: "" }
  if (ctx.firstLoad === true) {
    var np = ctx.nowPlaying
    var who = np ? { id: str(np.id), name: str(np.name) } : null
    var why = str(ctx.reason)
    var ended = str(ctx.ended)
    var lostFirst = ended === "end-file" ? outputFailure({ reason: "error", fileError: ctx.fileError }) : ""
    if (lostFirst !== "") return { notify: true, mark: false, card: "outputFailed", target: who, reason: outputFailureSentence(lostFirst), output: lostFirst }
    if (ended === "closed") return { notify: true, mark: false, card: "playerStopped", target: who, reason: PLAYER_GENERIC_FAILURE, output: "" }
    var formatFirst = ended === "end-file" ? unopenedFormatSentence({ reason: "error", fileError: ctx.fileError }) : ""
    return { notify: true, mark: true, card: "streamFailed", target: who,
             reason: formatFirst !== "" ? formatFirst : why !== "" ? why : PLAYER_GENERIC_FAILURE, output: "" }
  }
  var report = endedReport(ctx)
  if (report.notify !== true) return { notify: false, mark: false, card: "", target: report.target, reason: "", output: "" }
  var lost = outputFailure(ctx.lastEndFile)
  if (lost !== "") return { notify: true, mark: false, card: "outputFailed", target: report.target, reason: outputFailureSentence(lost), output: lost }
  if (loadFailedForOwnEntry(ctx.lastEndFile, ctx.owners, ctx.entryId)) {
    return { notify: true, mark: true, card: "streamFailed", target: report.target, reason: report.reason, output: "" }
  }
  return { notify: true, mark: false, card: "playerStopped", target: report.target, reason: PLAYER_GENERIC_FAILURE, output: "" }
}

// deathReport's evidence test: an end-file "error" for an entry the ring
// owns, or, the ring silent, for the entry the player last started.
function loadFailedForOwnEntry(end, owners, currentEntryId) {
  if (!end || typeof end !== "object" || str(end.reason) !== "error") return false
  var id = playerEntryId(end.entryId)
  if (id === null) return false
  if (owners && typeof owners === "object" && ownKeyValue(owners, String(id))) return true
  return id === playerEntryId(currentEntryId)
}
